        // MARK: Dummy Subject
        public class DummySubject
        {
            public Character Character { get; }
            public int DeathId { get; }

            public DummySubject(Character character, int deathId)
            {
                Character = character;
                DeathId = deathId;
            }

            public void SetupDummyEntity()
            {
                Character.CharacterList.Remove(Character);

                Character.AnimController.Frozen = true;
                Character.DisableInteract = true;
                Character.NeedsAir = false;

                ApplyInertia();

                Character.CharacterHealth.SetHealthBarVisibility(false);
                if (Character.CharacterHealth.SuicideButton != null) Character.CharacterHealth.SuicideButton.Visible = false;
                if (Character.CharacterHealth.CPRButton != null) Character.CharacterHealth.CPRButton.Visible = false;
            }

            public void ApplyInertia()
            {
                Character.AnimController.SimplePhysicsEnabled = true;
                Character.InvisibleTimer = float.MaxValue;

                if (Character.AiTarget != null)
                {
                    Character.AiTarget.InDetectable = true;
                    Character.AiTarget.SoundRange = 0f;
                    Character.AiTarget.SightRange = 0f;
                }
            }

            public void Discard()
            {
                RescueNativeWindow();
                if (CharacterHealth.OpenHealthWindow == Character.CharacterHealth)
                    MedicalReflector.OpenHealthWindowField?.SetValue(null, null);

                if (!Character.Removed)
                {
                    if (Character.Inventory != null)
                    {
                        foreach (var item in Character.Inventory.AllItems.ToList()) item.Remove();
                    }
                    Character.Remove();
                }
            }
        }

        public static void Initialize(int savedDeathCount, string? savedXml, bool savedSimulated = false)
        {
            MedicalReflector.Validate();
            if (ActiveDummy != null && ActiveDummy.Character != null && !ActiveDummy.Character.Removed) return;
            ActiveDummy?.Discard();
            ActiveDummy = null;
            DeathCount = savedDeathCount;

            bool loadedSuccessfully = false;
            if (!string.IsNullOrEmpty(savedXml))
            {
                try
                {
                    XElement element = XElement.Parse(savedXml);

                    var charNode = element.Name.ToString().Equals("Character", StringComparison.OrdinalIgnoreCase)
                        ? element
                        : element.Element("Character");

                    if (charNode != null)
                    {
                        var contentX = new ContentXElement(null, charNode);
                        CharacterInfo info = new(contentX);

                        var character = Character.Create(info.SpeciesName, new Vector2(0, -10000), "SOS_DUMMY", info, isRemotePlayer: false, hasAi: false, createNetworkEvent: false, spawnInitialItems: false, id: GetFreshDummyID());
                        ActiveDummy = new DummySubject(character, DeathCount);
                        ActiveDummy.SetupDummyEntity();

                        XElement? healthNode = element.Element("health");
                        if (healthNode != null)
                        {
                            CharacterInfo.ApplyHealthData(Patient, healthNode);
                            MedicalReflector.HealthBiologicalUpdateMethod?.Invoke(Patient?.CharacterHealth, [0f]);
                            Patient?.CharacterHealth.CalculateVitality();
                        }

                        loadedSuccessfully = true;
                    }
                }
                catch (Exception e)
                {
                    LuaCsLogger.LogError($"[SOS] Failed to load saved Dummy XML: {e.Message}");
                }
            }

            if (!loadedSuccessfully)
            {
                CreateNewDummy();
            }

            IsPlaying = false;
            if (loadedSuccessfully && savedSimulated)
            {
                HasStarted = false;
                TakeSnapshot();
            }
            else
            {
                HasStarted = true;
                snapshot = null;
            }
        }

        private static void CreateNewDummy()
        {
            CharacterPrefab? prefab = CharacterPrefab.HumanPrefab;

            CharacterInfo info = new(prefab.Identifier, name: "Dummy", originalName: "SOS Dummy", jobOrJobPrefab: JobPrefab.Get("assistant")); //assistant, medicaldoctor
            AssignSubjectIdentity(info, DeathCount);

            Character? character = Character.Create(prefab, new Vector2(0, -10000), "SOS_DUMMY", info, isRemotePlayer: false, hasAi: false, createNetworkEvent: false, spawnInitialItems: false, id: GetFreshDummyID());
            ActiveDummy = new DummySubject(character, DeathCount);
            ActiveDummy.SetupDummyEntity();
        }

        private static void AssignSubjectIdentity(CharacterInfo info, int deathCount)
        {
            string nameTemplate;
            if (deathCount < 50)
            {
                int tier = deathCount / 10;
                if (tier == 0) tier = 1;
                nameTemplate = TextSOS.Get($"sos.dummyname.rand.{tier}", $"Dummy Subject #[id]").Value;
            }
            else
            {
                var randomNames = TextSOS.GetTranslationsByPrefix("sos.dummyname.rand.").Values.ToImmutableArray();
                if (randomNames.Length > 0)
                    nameTemplate = randomNames[Rand.Range(0, randomNames.Length)];
                else
                    nameTemplate = "Subject #[id]";
            }

            string finalName = nameTemplate.Replace("[id]", deathCount.ToString());
            RLogger.LogDebug("[SOS] Assigning Subject Identity: " + finalName);
            info.Name = finalName;
            info.OriginalName = finalName;
        }

        public static void DiscardPatient()
        {
            DeathCount++;

            ActiveDummy?.Discard();

            CreateNewDummy();

            IsPlaying = false;
            HasStarted = true;
            snapshot = null;
        }

        public static void Update(float deltaTime)
        {
            if (Patient?.CharacterHealth == null || Patient.Removed) return;

            if (Patient.InvisibleTimer < 1.0f) Patient.InvisibleTimer = float.MaxValue;

            Patient.CharacterHealth.UpdateClientSpecific(deltaTime);

            if (IsPlaying)
            {
                if (HasStarted)
                {
                    TakeSnapshot();
                    HasStarted = false;
                }
                float dt = deltaTime * TimeScale;
                MedicalReflector.HealthBiologicalUpdateMethod?.Invoke(Patient.CharacterHealth, [dt]);
            }

            var controlled = Character.Controlled;
            if (controlled == null) return;

            var prevSelected = MedicalReflector.SelectedCharField?.GetValue(controlled) as Character;
            MedicalReflector.SelectedCharField?.SetValue(controlled, Patient);

            var prevOpenHealthWindow = MedicalReflector.OpenHealthWindowField?.GetValue(null) as CharacterHealth;
            MedicalReflector.OpenHealthWindowField?.SetValue(null, Patient.CharacterHealth);

            if (MedicalReflector.CharacterNameField?.GetValue(Patient.CharacterHealth) is GUITextBlock nameBlock)
            {
                nameBlock.Text = Patient.Info == null || Patient == Character.Controlled

                    ? Patient.Name

                    : Patient.Info.DisplayName;
            }

            Patient.CharacterHealth.UpdateHUD(deltaTime);

            if (Patient.CharacterHealth.CPRButton != null)
            {
                Patient.CharacterHealth.CPRButton.Visible = false;
            }
            if (Patient.CharacterHealth.SuicideButton != null)
            {
                Patient.CharacterHealth.SuicideButton.Visible = false;
            }

            MaybeKillDummy();

            if (MedicalReflector.TooltipField?.GetValue(Patient.CharacterHealth) is GUIComponent tooltip)
            {
                tooltip.AddToGUIUpdateList(ignoreChildren: false, order: 100000);
            }

            if (MedicalReflector.TreatmentContainerField?.GetValue(Patient.CharacterHealth) is GUIListBox treatmentList)
            {
                foreach (GUIComponent component in treatmentList.Content.Children)
                {
                    if (component.GetChild<GUIButton>() is GUIButton treatmentBtn && treatmentBtn.UserData is ItemPrefab medPrefab)
                    {
                        bool wasDisabled = !treatmentBtn.Enabled;

                        treatmentBtn.Enabled = true;
                        foreach (var child in treatmentBtn.Children) child.Enabled = true;

                        treatmentBtn.OnClicked = (btn, userData) =>
                        {
                            int selectedIndex = (int)(MedicalReflector.SelectedLimbIndexField?.GetValue(Patient.CharacterHealth) ?? -1);
                            Limb? targetLimb = selectedIndex >= 0 ? Patient.AnimController.Limbs.FirstOrDefault(l => l.HealthIndex == selectedIndex) : null;

                            ApplyMockItem(medPrefab, targetLimb);
                            return true;
                        };

                        if (wasDisabled)
                        {
                            string colorHex = Color.LightSkyBlue.ToStringHex();
                            treatmentBtn.ToolTip = RichString.Rich($"‖color:{colorHex}‖[SIMULATION MODE]‖color:end‖\n‖color:255,255,255,255‖{medPrefab.Name.Value}‖color:end‖\n{medPrefab.Description}");
                        }
                    }
                }
            }

            MedicalReflector.OpenHealthWindowField?.SetValue(null, prevOpenHealthWindow);
            MedicalReflector.SelectedCharField?.SetValue(controlled, prevSelected);
        }

        public static void ApplyMockItem(ItemPrefab prefab, Limb? targetLimb)
        {
            if (Patient == null) return;
            Item? mockItem = null;
            try
            {
                mockItem = new Item(prefab, Vector2.Zero, null, id: GetFreshMockID());

                Patient.Inventory?.TryPutItem(mockItem, Patient, CharacterInventory.AnySlot, false, false);

                var user = Character.Controlled ?? Patient;
                var target = targetLimb ?? Patient.AnimController.MainLimb;

                var meleeWeapon = mockItem.GetComponent<Barotrauma.Items.Components.MeleeWeapon>();
                var projectile = mockItem.GetComponent<Barotrauma.Items.Components.Projectile>();

                if (meleeWeapon?.Attack != null)
                {
                    meleeWeapon.Attack.DoDamageToLimb(
                        attacker: user,
                        targetLimb: target,
                        worldPosition: target.WorldPosition,
                        deltaTime: 1.0f,
                        playSound: false
                    );

                    //SoundPlayer.PlaySound("LimbSlash", 100f);
                }
                else if (projectile?.Attack != null)
                {
                    projectile.Attack.DoDamageToLimb(
                        attacker: user,
                        targetLimb: target,
                        worldPosition: target.WorldPosition,
                        deltaTime: 1.0f,
                        playSound: false
                    );

                    //SoundPlayer.PlaySound("LimbSlash", 100f);
                }
                else
                {
                    foreach (var ic in mockItem.Components)
                    {
                        if (!ic.HasRequiredContainedItems(user, addMessage: false)) continue;

                        bool success = Rand.Range(0.0f, 0.5f) < ic.DegreeOfSuccess(user);
                        var conditionalType = success ? ActionType.OnSuccess : ActionType.OnFailure;

                        ic.ApplyStatusEffects(conditionalType, 1.0f, Patient, target, useTarget: Patient, user: user);
                        ic.ApplyStatusEffects(ActionType.OnUse, 1.0f, Patient, target, useTarget: Patient, user: user);

                        SoundPlayer.PlayUISound(GUISoundType.PickItem);
                    }
                }
            }
            catch (Exception e)
            {
                LuaCsLogger.LogError($"[SOS] Simulation Mock Item Error: {e.Message}");
            }
            finally
            {
                if (mockItem != null && !mockItem.Removed)
                {
                    mockItem.ParentInventory?.RemoveItem(mockItem);
                    Entity.Spawner?.AddItemToRemoveQueue(mockItem);
                }
            }
        }

        public static void MaybeKillDummy()
        {
            if (Patient == null || Patient.IsDead || Patient.CharacterHealth.Vitality > -100.0f) return;

            MedicalReflector.IsDeadField?.SetValue(Patient, true);

            var (type, affliction) = Patient.CharacterHealth.GetCauseOfDeath();
            Patient.CauseOfDeath = new CauseOfDeath(
                type,
                affliction?.Prefab,
                affliction?.Source,
                Patient.LastDamageSource
            );

            if (Patient.Info != null)
            {
                Patient.Info.CauseOfDeath = Patient.CauseOfDeath;
            }

            Patient.AnimController.movement = Vector2.Zero;
            Patient.AnimController.TargetMovement = Vector2.Zero;
            Patient.SelectedItem = null;
            Patient.SelectedSecondaryItem = null;
            Patient.SelectedCharacter = null;

            Patient.CharacterHealth?.CalculateVitality();
            IsPlaying = false;
        }

        public static void InjectAffliction(AfflictionPrefab prefab, float strength, Limb? targetLimb = null)
        {
            if (Patient?.CharacterHealth == null) return;
            var inst = prefab.Instantiate(strength);
            var limb = targetLimb ?? Patient.AnimController.GetLimb(prefab.IndicatorLimb != LimbType.None ? prefab.IndicatorLimb : LimbType.Torso) ?? Patient.AnimController.MainLimb;
            Patient.CharacterHealth.ApplyAffliction(limb, inst);
        }

        public static void RemoveAffliction(AfflictionPrefab prefab, Limb? targetLimb = null)
        {
            if (Patient?.CharacterHealth == null) return;

            if (targetLimb != null)
            {
                var aff = Patient.CharacterHealth.GetAffliction(prefab.Identifier, targetLimb);
                if (aff != null) Patient.CharacterHealth.ReduceAfflictionOnLimb(targetLimb, prefab.Identifier, aff.Strength);
            }
            else
            {
                var aff = Patient.CharacterHealth.GetAffliction(prefab.Identifier);
                if (aff != null) Patient.CharacterHealth.ReduceAfflictionOnAllLimbs(prefab.Identifier, aff.Strength);
            }
        }

        public static void SetAfflictionStrength(AfflictionPrefab prefab, float strength, Limb? targetLimb = null)
        {
            if (Patient?.CharacterHealth == null) return;

            var aff = targetLimb != null ?
                Patient.CharacterHealth.GetAffliction(prefab.Identifier, targetLimb) :
                Patient.CharacterHealth.GetAffliction(prefab.Identifier);

            if (aff != null)
            {
                float diff = strength - aff.Strength;
                if (diff > 0) InjectAffliction(prefab, diff, targetLimb);
                else
                {
                    if (targetLimb != null) Patient.CharacterHealth.ReduceAfflictionOnLimb(targetLimb, prefab.Identifier, -diff);
                    else Patient.CharacterHealth.ReduceAfflictionOnAllLimbs(prefab.Identifier, -diff);
                }
            }
            else if (strength > 0)
            {
                InjectAffliction(prefab, strength, targetLimb);
            }
        }

        public static void ResetPatient()
        {
            if (Patient == null) return;

            Patient.Revive();
            ActiveDummy?.ApplyInertia();

            Patient.CharacterHealth?.RemoveAllAfflictions();

            if (snapshot != null)
            {
                foreach (var (prefab, strength, limbType) in snapshot)
                {
                    var limb = Patient.AnimController.GetLimb(limbType);
                    InjectAffliction(prefab, strength, limb);
                }
            }

            Patient.CharacterHealth?.CalculateVitality();
            IsPlaying = false;
            HasStarted = true;
        }

        public static void CleanPatient()
        {
            if (Patient == null) return;
            Patient.Revive();
            ActiveDummy?.ApplyInertia();
            Patient.CharacterHealth?.RemoveAllAfflictions();
            Patient.CharacterHealth?.CalculateVitality();
            IsPlaying = false;
            HasStarted = true;
            snapshot = null;
        }

        private static void TakeSnapshot()
        {
            if (Patient?.CharacterHealth == null) return;
            snapshot = [];
            foreach (var aff in Patient.CharacterHealth.GetAllAfflictions())
            {
                var limb = Patient.CharacterHealth.GetAfflictionLimb(aff);
                snapshot.Add((aff.Prefab, aff.Strength, limb?.type ?? LimbType.Torso));
            }
        }

        // AI modified to add null safety and exception handling for the native window.
        public static void RescueNativeWindow()
        {
            if (Patient?.CharacterHealth != null)
            {
                MedicalReflector.HighlightedLimbField?.SetValue(Patient.CharacterHealth, -1);
                MedicalReflector.SelectedLimbIndexField?.SetValue(Patient.CharacterHealth, -1);
            }

            if (hijackedNativeWindow != null)
            {
                try
                {
                    if (hijackedNativeWindow.RectTransform != null)
                    {
                        hijackedNativeWindow.RectTransform.Parent = null;
                    }
                }
                catch (System.Exception e)
                {
                    RLogger.LogWarning($"[SOS] Safety warning during native window rescue: {e.Message}");
                }
                finally
                {
                    hijackedNativeWindow = null;
                }
            }
        }

        public static XElement? ExportSaveData()
        {
            if (Patient == null) return null;

            try
            {
                XElement root = Patient.Info.Save(null);

                XElement healthElement = new("health");
                Patient.CharacterHealth.Save(healthElement);

                root.Add(healthElement);

                return root;
            }
            catch (Exception e)
            {
                LuaCsLogger.LogError($"[SOS] Error exporting native Dummy save data: {e.Message}");
                return null;
            }
        }

        public static void Destroy()
        {
            RescueNativeWindow();

            if (CharacterHealth.OpenHealthWindow == Patient?.CharacterHealth)
                MedicalReflector.OpenHealthWindowField?.SetValue(null, null);

            if (Patient?.Inventory != null)
            {
                foreach (var item in Patient.Inventory.AllItems.ToList())
                {
                    item.Remove();
                }
            }

            if (Patient != null && !Patient.Removed)
            {
                Patient.Remove();
            }
            ActiveDummy = null;
        }
    }
